from dataclasses import dataclass, field
from enum import Enum

class Op(Enum):
    CREATE = "create"        # a fact the store has never seen
    UPDATE = "update"        # same fact still true, a detail added or fixed
    REINFORCE = "reinforce"  # same fact, more support, nothing changes
    SUPERSEDE = "supersede"  # the old fact stopped being true

@dataclass
class Entry:
    key: str                                  # e.g. "owner(billing-service)"
    value: str
    support: list[str] = field(default_factory=list)  # chunk ids behind it
    superseded_by: str | None = None

def live(store, key):
    return [e for e in store.get(key, []) if e.superseded_by is None]

def write(store, chunk_id, key, value, op: Op):
    history = store.setdefault(key, [])
    current = live(store, key)
    if op is Op.CREATE or not current:
        # CREATE on a key that already has a live entry = two live owners.
        history.append(Entry(key, value, [chunk_id]))
    elif op is Op.REINFORCE:
        current[-1].support.append(chunk_id)
    elif op is Op.UPDATE:
        current[-1].value = value
        current[-1].support.append(chunk_id)
    elif op is Op.SUPERSEDE:
        for e in current:
            e.superseded_by = chunk_id         # retired, kept as history
        history.append(Entry(key, value, [chunk_id]))

# The hard part is not this function. It is whatever chose `op`.
